const xml = $input.item.json.data || $input.item.json.body || '';
const matches = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map(m => m[1]);
const limited = matches.slice(0, 100);
return limited.map(url => ({ json: { url } }));

const clusters = $('Parse Keyword Clusters').item.json;
const metaUpdatedCount = $('Get Pages Missing Meta Description').all().length;
const brokenLinks = $('Collect Broken Link').all().map(i => i.json);

const html = `
  <h2>Weekly SEO Report</h2>
  <h3>Top Keyword Opportunities</h3>
  <ul>${(clusters.top_opportunity_keywords || []).map(k => `<li><b>${k.keyword}</b> - position ${k.current_position} - ${k.suggested_action}</li>`).join('')}</ul>
  <h3>Content Gap Topics</h3>
  <ul>${(clusters.content_gap_topics || []).map(t => `<li>${t}</li>`).join('')}</ul>
  <h3>Meta Descriptions Auto-Generated</h3>
  <p>${metaUpdatedCount} pages updated this week</p>
  <h3>Broken Links Found</h3>
  <ul>${brokenLinks.length ? brokenLinks.map(b => `<li>${b.broken_url} (status ${b.status_code})</li>`).join('') : '<li>None found 🎉</li>'}</ul>
`;

return [{ json: { reportHtml: html } }];

const body = $input.item.json.body || $input.item.json;

// Typebot generally sends answers as an array of {key, value} or a flat object depending on setup.
