// Guard: don't call an unconfigured provider. Matches §76 Mocking rule —
// never present a mock as production integration, and don't fail loudly
// on a decision that's explicitly still open (tool choice unconfirmed).
const apiKey = $env.PHANTOMBUSTER_API_KEY || '';
const agentId = $env.PHANTOMBUSTER_LINKEDIN_INBOX_AGENT_ID || '';
return [{
  json: {
    providerConfigured: Boolean(apiKey && agentId)
  }
}];

// Fetch failed (network/auth/rate-limit). No retry queue yet for this
// module — same known-gap pattern flagged in 4.3.1's README. Left visible
// in the execution log rather than silently swallowed.
const j = $input.item.json;
return [{ json: { ...j, fetchFailed: true } }];

// 4.3.2.3 - New-replies parse Code node
// Normalizes whatever the configured provider returned into one item per
// inbound LinkedIn message. PhantomBuster's LinkedIn-inbox agents typically
// return an array of message objects in a 'resultObject' or top-level array —
// exact shape depends on which agent Nivy ends up using, so this reads a few
// common field-name variants defensively rather than assuming one exact schema.

const raw = $input.item.json;
let messages = [];

if (Array.isArray(raw)) {
  messages = raw;
} else if (Array.isArray(raw.resultObject)) {
  messages = raw.resultObject;
} else if (typeof raw.resultObject === 'string') {
  try { messages = JSON.parse(raw.resultObject); } catch (e) { messages = []; }
} else if (Array.isArray(raw.data)) {
  messages = raw.data;
}

if (!Array.isArray(messages)) messages = [];

return messages.map(m => {
  const profileUrl = m.profileUrl || m.linkedinProfileUrl || m.senderProfileUrl || null;
  const senderName = m.senderName || m.name || m.fromName || '';
  const messageText = (m.message || m.text || m.body || '').toString().slice(0, 4000);
  const messageId = m.messageId || m.id || (profileUrl && m.timestamp ? `${profileUrl}:${m.timestamp}` : null);
  const messageTimestamp = m.timestamp
    ? new Date(m.timestamp).toISOString()
    : new Date().toISOString();

  return {
    json: {
      messageId,
      profileUrl,
      senderName,
      messageText,
      messageTimestamp
    }
  };
}).filter(item => item.json.messageId); // skip anything we can't dedupe on

// DB update failed — deliberately NOT marking this message as processed,
// so the next poll cycle retries it (matches §16.3's 'leave unmarked-complete
// on failure so a legitimate retry can still succeed' standard).
const j = $input.item.json;
return [{ json: { ...j, updateFailed: true } }];

// 4.3.3.1 (part 1) - Validate + normalize the merged reply signal
const item = $input.item.json;

const errors = [];
if (!item.client_id && !item.email) errors.push('client_id or email required');
if (!item.channel) errors.push('channel required');
if (!['email','whatsapp','linkedin'].includes((item.channel||'').toLowerCase())) errors.push('channel must be email|whatsapp|linkedin');
if (!item.occurred_at) errors.push('occurred_at required');

const normalized = {
  client_id: item.client_id || null,
  email: item.email ? String(item.email).trim().toLowerCase() : null,
  channel: item.channel ? String(item.channel).trim().toLowerCase() : null,
  reply_content: item.reply_content || '',
  occurred_at: item.occurred_at || new Date().toISOString(),
  workflow_source: item.workflow_source || 'unknown',
  is_valid: errors.length === 0,
  validation_errors: errors.join('; ')
};

return [{ json: normalized }];

