const items = $input.all();
if (items.length === 0) return [];
const lines = items.map(i => `- ${i.json.name} (${i.json.company || 'n/a'}) -- NPS promoters: ${i.json.promoter_survey_count}, referrals: ${i.json.successful_referral_count}`).join('\n');
return [{ json: { summary: lines, count: items.length } }];

