parameters.jsCode:
const d = $json;
const sent = d.sent || 0;
const bounced = d.bounced || 0;
const complaints = d.complaints || 0;
const bounceRate = sent > 0 ? (bounced / sent) * 100 : 0;
const complaintRate = sent > 0 ? (complaints / sent) * 100 : 0;
return [{ json: { sent, bounced, complaints, bounce_rate_pct: bounceRate, complaint_rate_pct: complaintRate, over_threshold: bounceRate > 5 || complaintRate > 0.1 } }];

